  "legal": {
   "privacy": {
    "title": "سياسة الخصوصية",
    "updated": "2024-10-23",
    "content": "سياسة الخصوصية \n<p><strong>تم تحديثها:</strong> 23 أكتوبر 2024</p>\n \n<p>نحن في بنك المبادرات ملتزمون بحماية خصوصية المستخدمين وضمان أمان المعلومات الشخصية التي يتم جمعها. تشرح سياسة الخصوصية هذه كيفية تعاملنا مع المعلومات التي تقدمها عند استخدامك لموقعنا.</p><p><strong>المعلومات التي نجمعها</strong> عند استخدامك لموقعنا أو التفاعل معنا، قد نجمع بعض المعلومات الشخصية بما في ذلك، على سبيل المثال لا الحصر:</p><ul><li>الاسم الكامل</li><li>عنوان البريد الإلكتروني</li><li>رقم الهاتف</li><li>المعلومات الديموغرافية (مثل العمر والجنس)</li><li>بيانات تسجيل الدخول وملفات تعريف الارتباط</li></ul><p><strong>استخدام المعلومات</strong> نستخدم المعلومات التي نجمعها للأغراض التالية:</p><ul><li>تحسين تجربة المستخدم وتقديم محتوى ملائم</li><li>إرسال التحديثات والمعلومات الهامة المتعلقة بخدماتنا</li><li>تحليل بيانات المستخدم لتطوير الموقع والمبادرات</li></ul><p><strong>مشاركة المعلومات</strong> نحن لا نشارك معلوماتك الشخصية مع أي طرف ثالث دون موافقتك، إلا في الحالات الضرورية للامتثال للقوانين أو لحماية حقوقنا القانونية.</p><p><strong>أمان البيانات</strong> نتخذ كافة التدابير اللازمة لضمان حماية بياناتك الشخصية من الوصول غير المصرح به أو الكشف أو التعديل أو الإتلاف. نستخدم تقنيات الحماية المناسبة، مثل التشفير وجدران الحماية.</p><p><strong>تعديلات سياسة الخصوصية</strong> قد نقوم بتحديث سياسة الخصوصية هذه من وقت لآخر. سنقوم بإشعارك بأي تغييرات جوهرية من خلال نشر السياسة المعدلة على موقعنا.</p><p><strong>حقوقك</strong> لديك الحق في الوصول إلى معلوماتك الشخصية التي نحتفظ بها، وطلب تعديل أو حذف أي بيانات غير دقيقة أو غير محدثة. يمكنك التواصل معنا في أي وقت لطرح استفساراتك حول الخصوصية.</p>"
   },
   "terms": {
    "title": "الشروط والأحكام",
    "updated": "2024-10-23",
    "content": "الشروط والأحكام \n<p><strong>تم تحديثها:</strong> 23 أكتوبر 2024</p>\n \n<p>مرحباً بكم في موقع بنك المبادرات. باستخدام هذا الموقع، فإنك توافق على الالتزام بالشروط والأحكام التالية. إذا كنت لا توافق على أي جزء من هذه الشروط، يرجى عدم استخدام الموقع.</p><p><strong>1. استخدام الموقع</strong> يُسمح باستخدام هذا الموقع لأغراض قانونية فقط وبما يتوافق مع القوانين واللوائح المعمول بها. يُمنع استخدام الموقع لأي نشاط غير قانوني أو ضار، بما في ذلك نشر أو توزيع أي مواد تنتهك حقوق الملكية الفكرية أو تحتوي على محتوى ضار أو مسيء.</p><p><strong>2. حقوق الملكية الفكرية</strong> يحتفظ بنك المبادرات بكافة حقوق الملكية الفكرية المتعلقة بالموقع والمحتوى المنشور عليه، بما في ذلك النصوص والصور والشعارات. يُمنع إعادة إنتاج أو توزيع أي محتوى دون الحصول على إذن مسبق منا.</p><p><strong>3. الروابط الخارجية</strong> قد يحتوي الموقع على روابط لمواقع خارجية. نحن غير مسؤولين عن محتوى أو ممارسات الخصوصية لهذه المواقع. يُنصح بمراجعة سياسات الخصوصية والشروط الخاصة بكل موقع تزوره.</p><p><strong>4. إخلاء المسؤولية</strong> يتم تقديم محتوى هذا الموقع “كما هو” دون أي ضمانات صريحة أو ضمنية. لا نتحمل أي مسؤولية عن أي أضرار مباشرة أو غير مباشرة قد تنجم عن استخدام الموقع أو الاعتماد على المعلومات المتاحة عليه.</p><p><strong>5. التعديلات</strong> نحتفظ بالحق في تعديل هذه الشروط والأحكام في أي وقت دون إشعار مسبق. يُنصح بمراجعة هذه الصفحة بشكل دوري للاطلاع على أي تغييرات.</p><p><strong>6. القانون المعمول به</strong> تخضع هذه الشروط والأحكام وتفسر وفقاً للقوانين المعمول بها في فلسطين. أي نزاعات تنشأ فيما يتعلق باستخدام الموقع ستكون خاضعة لاختصاص المحاكم المحلية.</p><p><strong>7. الاتصال بنا</strong> إذا كانت لديك أي استفسارات حول هذه الشروط والأحكام، يرجى التواصل معنا عبر البريد الإلكتروني أو الهاتف الموجودين في صفحة الاتصال.</p>"
   }
  },
