      "وقد نُفذت الورشات بواقع ورشتين يوميًا، حيث اعتمد الفريق على تبسيط المحتوى وتقديم أمثلة عملية وأنشطة تفاعلية مختلفة لتناسب تفاوت مستويات المعرفة لدى المشاركات.",
      "بالإضافة إلى ذلك، جرى في 11 ديسمبر تنفيذ تدريب عملي ومتخصص استهدف 10 شابات حول مبادئ تقديم الإسعاف النفسي الأولي (PFA).",
