      "جاءت المبادرة في إطار مشروع \"الوصول للجميع: تعزيز استقلالية وإدماج الأشخاص ذوي الإعاقة في قطاع غزة\" الذي ينفذه المنتدى بالشراكة مع جمعية العون الطبي للفلسطينيين MAP.",
