     "paragraphs": [
      "مبادرة إنسانية، مجتمعية، توعوية سريعة وعملية، تقوم على توفير استجابة للاحتياجات الإنسانية الملحة للأسر التي تضم أشخاصًا من ذوي الإعاقة في الحصول على مياه صالحة للشرب، في مخيمات النزوح، وتساهم في تحسين فرص تخزين المياه وتسهيل الوصول إليها، إلى جانب تعزيز الوعي المجتمعي بحقوق الأشخاص ذوي الإعاقة في سهولة الوصول للخدمات الأساسية."
     ]
