   "summary": "مبادرة فنية وثقافية استجابت للحاجة الملحة لدى اليافعات النازحات لتوفير مساحة آمنة للتعبير ومواجهة آثار الحرب والنزوح. تهدف المبادرة إلى تعزيز الصحة النفسية والشعور بالانتماء من خلال الدمج بين الفنون، الحكواتي، والهوية الفلسطينية، مما يمكنهن من تفريغ الضغوط وإعادة تنظيم الأفكار. ويتجسد هذا العمل في مشروع شخصي لكل مشاركة، وهو \"جورنال إبداعي\" خاص، يكون بمثابة أداة للتعبير العميق والربط بالجذور الثقافية بطريقة تفاعلية وممتعة.",
